        super(classifier, id, receiveDelta, parentInfo);
        this._receiverArgument = new OptionalSingleReferenceValueManager<IExpression>(SysMLv2Base.INSTANCE.SendActionUsage_receiverArgument, this);
        this._payloadArgument = new RequiredSingleReferenceValueManager<IExpression>(SysMLv2Base.INSTANCE.SendActionUsage_payloadArgument, this);
        this._senderArgument = new OptionalSingleReferenceValueManager<IExpression>(SysMLv2Base.INSTANCE.SendActionUsage_senderArgument, this);
        this._actionDefinition = new OptionalMultiReferenceValueManager<IBehavior>(SysMLv2Base.INSTANCE.IActionUsage_actionDefinition, this);
        this._occurrenceDefinition = new OptionalMultiReferenceValueManager<IClass>(SysMLv2Base.INSTANCE.IOccurrenceUsage_occurrenceDefinition, this);
