    getPropertyValueManager(property: Property): PropertyValueManager<unknown> {
        switch (property.key) {
            case SysMLv2Base.INSTANCE.IType_isAbstract.key: return this._isAbstract;
            case SysMLv2Base.INSTANCE.IType_isSufficient.key: return this._isSufficient;
            case SysMLv2Base.INSTANCE.IType_isConjugated.key: return this._isConjugated;
            case SysMLv2Base.INSTANCE.IElement_elementId.key: return this._elementId;
            case SysMLv2Base.INSTANCE.IElement_declaredShortName.key: return this._declaredShortName;
            case SysMLv2Base.INSTANCE.IElement_declaredName.key: return this._declaredName;
            case SysMLv2Base.INSTANCE.IElement_shortName.key: return this._shortName;
            case SysMLv2Base.INSTANCE.IElement_name.key: return this._name;
            case SysMLv2Base.INSTANCE.IElement_qualifiedName.key: return this._qualifiedName;
            case SysMLv2Base.INSTANCE.IElement_isImpliedIncluded.key: return this._isImpliedIncluded;
            case SysMLv2Base.INSTANCE.IElement_isLibraryElement.key: return this._isLibraryElement;
            case SysMLv2Base.INSTANCE.IRelationship_isImplied.key: return this._isImplied;
            default: return super.getPropertyValueManager(property);
        }
    }

